import Foundation
import DesignPilotSDK

/// Transpiles semantic AST elements into maintainable, adaptive SwiftUI source code.
public struct SwiftUILayoutGenerator: Sendable {
    public init() {}

    public func generate(ast: ASTElement, screenName: String) -> String {
        var subviews: [String] = []
        let mainBodyContent = renderElement(ast, indent: 3, subviews: &subviews)

        let sanitizedName = sanitizeName(screenName)

        var code = """
        //
        //  \(sanitizedName)View.swift
        //  Generated by DesignPilot SDK v1.0
        //  Adaptive SwiftUI Architecture
        //

        import SwiftUI

        public struct \(sanitizedName)View: View {
            @Environment(\\.colorScheme) private var colorScheme

            public init() {}

            public var body: some View {
        \(mainBodyContent)
            }
        }

        """

        if !subviews.isEmpty {
            code += "\n// MARK: - Subviews & Components\n\n"
            code += subviews.joined(separator: "\n\n")
            code += "\n"
        }

        code += """

        #Preview {
            NavigationStack {
                \(sanitizedName)View()
            }
        }
        """

        return code
    }

    private func renderElement(_ element: ASTElement, indent: Int, subviews: inout [String]) -> String {
        let pad = String(repeating: "    ", count: indent)

        switch element {
        case .container(let type, let box, let children, _):
            var containerLines: [String] = []

            switch type {
            case .scrollContainer(let axis):
                let axisStr = axis == .vertical ? ".vertical" : ".horizontal"
                containerLines.append("\(pad)ScrollView(\(axisStr), showsIndicators: false) {")
                for child in children {
                    containerLines.append(renderElement(child, indent: indent + 1, subviews: &subviews))
                }
                containerLines.append("\(pad)}")

            case .verticalStack(let spacing, let align):
                let alignStr = align == .leading ? ".leading" : (align == .trailing ? ".trailing" : ".center")
                containerLines.append("\(pad)VStack(alignment: \(alignStr), spacing: \(formatNumber(spacing))) {")
                for child in children {
                    containerLines.append(renderElement(child, indent: indent + 1, subviews: &subviews))
                }
                containerLines.append("\(pad)}")

            case .horizontalStack(let spacing, let align):
                let alignStr = align == .top ? ".top" : (align == .bottom ? ".bottom" : ".center")
                containerLines.append("\(pad)HStack(alignment: \(alignStr), spacing: \(formatNumber(spacing))) {")
                for child in children {
                    containerLines.append(renderElement(child, indent: indent + 1, subviews: &subviews))
                }
                containerLines.append("\(pad)}")

            case .overlayStack:
                containerLines.append("\(pad)ZStack {")
                for child in children {
                    containerLines.append(renderElement(child, indent: indent + 1, subviews: &subviews))
                }
                containerLines.append("\(pad)}")
            }

            // Apply Box Modifiers
            let modified = applyBoxModifiers(to: containerLines.joined(separator: "\n"), box: box, indent: indent)
            return modified

        case .text(let chars, let style, let colorHex, let isHeading, _):
            var lines: [String] = []
            let escapedChars = chars.replacingOccurrences(of: "\"", with: "\\\"")
            lines.append("\(pad)Text(\"\(escapedChars)\")")

            if let style = style {
                let weightStr = swiftUIFontWeight(style.fontWeight)
                lines.append("\(pad)    .font(.system(size: \(formatNumber(style.fontSize)), weight: .\(weightStr)))")
            } else if isHeading {
                lines.append("\(pad)    .font(.title2.weight(.bold))")
            } else {
                lines.append("\(pad)    .font(.body)")
            }

            if let hex = colorHex {
                lines.append("\(pad)    .foregroundColor(Color(hex: \"\(hex)\"))")
            } else {
                lines.append("\(pad)    .foregroundColor(.primary)")
            }

            if isHeading {
                lines.append("\(pad)    .accessibilityHeading(.h2)")
            }

            return lines.joined(separator: "\n")

        case .button(let title, let box, let actionName, _):
            var lines: [String] = []
            lines.append("\(pad)Button(action: { /* \(actionName) */ }) {")
            lines.append("\(pad)    Text(\"\(title)\")")
            lines.append("\(pad)        .font(.headline)")
            lines.append("\(pad)        .foregroundColor(.white)")
            lines.append("\(pad)}")
            let btnCode = lines.joined(separator: "\n")
            return applyBoxModifiers(to: btnCode, box: box, indent: indent, defaultButtonStyling: true)

        case .image(let asset, let box, let symbol, _):
            var lines: [String] = []
            if let sym = symbol {
                lines.append("\(pad)Image(systemName: \"\(sym)\")")
                lines.append("\(pad)    .font(.title3)")
            } else {
                lines.append("\(pad)Image(\"\(asset)\")")
                lines.append("\(pad)    .resizable()")
                lines.append("\(pad)    .scaledToFit()")
            }
            return applyBoxModifiers(to: lines.joined(separator: "\n"), box: box, indent: indent)

        case .spacer(let minSize):
            if let min = minSize, min > 0 {
                return "\(pad)Spacer(minLength: \(formatNumber(min)))"
            }
            return "\(pad)Spacer()"

        case .divider:
            return "\(pad)Divider()"
        }
    }

    private func applyBoxModifiers(to baseCode: String, box: LayoutBox, indent: Int, defaultButtonStyling: Bool = false) -> String {
        var lines = [baseCode]
        let pad = String(repeating: "    ", count: indent)

        // Frames / Sizing
        switch (box.width, box.height) {
        case (.fill, .fill):
            lines.append("\(pad)    .frame(maxWidth: .infinity, maxHeight: .infinity)")
        case (.fill, .fixed(let h)):
            lines.append("\(pad)    .frame(maxWidth: .infinity, minHeight: \(formatNumber(h)))")
        case (.fixed(let w), .fill):
            lines.append("\(pad)    .frame(width: \(formatNumber(w)), maxHeight: .infinity)")
        case (.fixed(let w), .fixed(let h)):
            lines.append("\(pad)    .frame(width: \(formatNumber(w)), height: \(formatNumber(h)))")
        case (.fill, .hug):
            lines.append("\(pad)    .frame(maxWidth: .infinity)")
        case (.hug, .fill):
            lines.append("\(pad)    .frame(maxHeight: .infinity)")
        case (.hug, .fixed(let h)):
            lines.append("\(pad)    .frame(height: \(formatNumber(h)))")
        case (.fixed(let w), .hug):
            lines.append("\(pad)    .frame(width: \(formatNumber(w)))")
        case (.hug, .hug):
            break
        }

        // Padding
        if box.paddingTop > 0 || box.paddingBottom > 0 || box.paddingLeft > 0 || box.paddingRight > 0 {
            if box.paddingTop == box.paddingBottom && box.paddingLeft == box.paddingRight && box.paddingTop == box.paddingLeft {
                lines.append("\(pad)    .padding(\(formatNumber(box.paddingTop)))")
            } else if box.paddingLeft == box.paddingRight && box.paddingTop == box.paddingBottom {
                lines.append("\(pad)    .padding(.horizontal, \(formatNumber(box.paddingLeft)))")
                lines.append("\(pad)    .padding(.vertical, \(formatNumber(box.paddingTop)))")
            } else {
                lines.append("\(pad)    .padding(EdgeInsets(top: \(formatNumber(box.paddingTop)), leading: \(formatNumber(box.paddingLeft)), bottom: \(formatNumber(box.paddingBottom)), trailing: \(formatNumber(box.paddingRight))))")
            }
        }

        // Background
        if let hex = box.backgroundColorHex {
            lines.append("\(pad)    .background(Color(hex: \"\(hex)\"))")
        } else if defaultButtonStyling {
            lines.append("\(pad)    .background(Color.blue)")
        }

        // Corner Radius
        if box.cornerRadius > 0 {
            lines.append("\(pad)    .clipShape(RoundedRectangle(cornerRadius: \(formatNumber(box.cornerRadius)), style: .continuous))")
        } else if defaultButtonStyling {
            lines.append("\(pad)    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))")
        }

        // Shadow
        if let shadowRad = box.shadowRadius, shadowRad > 0 {
            let sx = box.shadowOffset?.x ?? 0
            let sy = box.shadowOffset?.y ?? 0
            lines.append("\(pad)    .shadow(color: Color.black.opacity(0.1), radius: \(formatNumber(shadowRad)), x: \(formatNumber(sx)), y: \(formatNumber(sy)))")
        }

        return lines.joined(separator: "\n")
    }

    private func swiftUIFontWeight(_ weight: String) -> String {
        switch weight.lowercased() {
        case "bold": return "bold"
        case "semibold": return "semibold"
        case "medium": return "medium"
        case "light": return "light"
        default: return "regular"
        }
    }

    private func formatNumber(_ val: Double) -> String {
        if val.truncatingRemainder(dividingBy: 1) == 0 {
            return "\(Int(val))"
        }
        return String(format: "%.1f", val)
    }

    private func sanitizeName(_ name: String) -> String {
        let cleaned = name.components(separatedBy: CharacterSet.alphanumerics.inverted).joined()
        return cleaned.isEmpty ? "GeneratedScreen" : cleaned
    }
}
